insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'microbes', 'Fungus: Diversity', 'Fungi have a worldwide distribution, and grow in a wide range of habitats, including extreme environments such as deserts or areas with high salt concentrations or ionizing radiation, as well as in deep sea sediments. Some can survive the intense UV and cosmic radiation encountered during space travel. Most grow in terrestrial environments, though several species live partly or solely in aquatic habitats, such as the chytrid fungi Batrachochytrium dendrobatidis and B. salamandrivorans, parasites that have been responsible for a worldwide decline in amphibian populations. These organisms spend part of their life cycle as a motile zoospore, enabling them to propel themselves through water and enter their amphibian host. Other examples of aquatic fungi include those living in hydrothermal areas of the ocean.', 'Wikipedia: Fungus', 'https://en.wikipedia.org/w/index.php?title=Fungus&oldid=1380904850', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
